import { plus as add, truth } from "./math.zry";
function helper(value: i32): i32 { return value; }
export function main(x: i32): i32 {
  const enabled: bool = truth();
  let y: i32 = -x * 2;
  if (enabled) { y = add(y, 1); } else { y = y - 1; }
  while (y < 10) { y = y + 1; }
  { const copy: i32 = y; }
  return y;
}
